trans = {("q0", "0"): ("q1", "1", "R"), ("q1", "0"): ("q2", "0", "R"), ("q2", "\u25a1"): ("qaccept", "\u25a1", "L")}
tape = ["0", "0"]
head = 0
state = "q0"
moves = 0
while True:
    sym = tape[head] if head < len(tape) else "\u25a1"
    if (state, sym) not in trans:
        break
    ns, ws, d = trans[(state, sym)]
    if head < len(tape):
        tape[head] = ws
    else:
        while len(tape) < head:
            tape.append("\u25a1")
        tape.append(ws)
    state = ns
    head += 1 if d == "R" else -1
    moves += 1
print(moves)
